using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private void AssertDefaultTaskBindingProof(CombatState live)
    {
        SetStage("default_task_binding_proof");
        using var input = JsonDocument.Parse(typeof(UnattendedTestRunner).Assembly
            .GetManifestResourceStream("CombatSolver.NativeDefaultTaskDefinitions.json")!);
        Guid gameMvid = input.RootElement.GetProperty("game").GetProperty("mvid").GetGuid();
        if (typeof(AbstractModel).Module.ModuleVersionId != gameMvid)
            throw new InvalidOperationException("Different game module.");
        string before = ContinuationStamp.CaptureLive(live).StateText;
        var receiver = (DefendSilent)RuntimeHelpers.GetUninitializedObject(typeof(DefendSilent));
        MethodInfo getter = typeof(Task).GetProperty(nameof(Task.CompletedTask))!.GetMethod!;
        byte[] getterIl = getter.GetMethodBody()!.GetILAsByteArray()!;
        // A definition-local claim only: one exact static field read and ret.
        if (getterIl.Length != 6 || getterIl[0] != 0x7e || getterIl[5] != 0x2a)
            throw new InvalidOperationException("Unknown CompletedTask getter body.");
        FieldInfo completedField = getter.Module.ResolveField(BitConverter.ToInt32(getterIl, 1))!;
        if (!completedField.IsStatic || !completedField.IsInitOnly || completedField.FieldType != typeof(Task)
            || !ReferenceEquals(completedField.GetValue(null), Task.CompletedTask))
            throw new InvalidOperationException("Unexpected completed task field or value.");
        Assembly facade = Assembly.Load("System.Runtime");
        if (facade.GetType("System.Threading.Tasks.Task", throwOnError: true) != typeof(Task))
            throw new InvalidOperationException("Unresolved System.Runtime Task forwarding.");
        int PatchCount(MethodInfo method) => Harmony.GetPatchInfo(method)?.Prefixes.Count
            + Harmony.GetPatchInfo(method)?.Postfixes.Count + Harmony.GetPatchInfo(method)?.Transpilers.Count
            + Harmony.GetPatchInfo(method)?.Finalizers.Count ?? 0;
        if (PatchCount(getter) != 0)
            throw new InvalidOperationException("Unknown completed task getter patch.");
        List<object> methods = [];
        List<MethodInfo> invoked = [];
        foreach (JsonElement definition in input.RootElement.GetProperty("definitions").EnumerateArray())
        {
            var method = (MethodInfo)typeof(AbstractModel).Module.ResolveMethod(definition.GetProperty("DefinitionToken").GetInt32())!;
            byte[] il = method.GetMethodBody()!.GetILAsByteArray()!;
            string digest = Convert.ToHexString(SHA256.HashData(il)).ToLowerInvariant();
            if (digest != definition.GetProperty("IlSha256").GetString() || method.ReturnType != typeof(Task)
                || PatchCount(method) != 0 || il.Length != 6 || il[0] != 0x28 || il[5] != 0x2a)
                throw new InvalidOperationException("Unknown default callback body or patch: " + method.Name);
            var callee = (MethodInfo)method.Module.ResolveMethod(BitConverter.ToInt32(il, 1))!;
            if (callee.Module.ModuleVersionId != getter.Module.ModuleVersionId || callee.MetadataToken != getter.MetadataToken)
                throw new InvalidOperationException("Different resolved Task dependency.");
            MethodInfo selected = receiver.GetType().GetMethod(method.Name, method.GetParameters().Select(p => p.ParameterType).ToArray())!;
            if (selected.Module.ModuleVersionId != method.Module.ModuleVersionId || selected.MetadataToken != method.MetadataToken)
                throw new InvalidOperationException("Receiver overrides reviewed default.");
            object?[] arguments = new object?[method.GetParameters().Length];
            var task = (Task)method.Invoke(receiver, arguments)!;
            if (!ReferenceEquals(task, Task.CompletedTask) || !task.IsCompletedSuccessfully)
                throw new InvalidOperationException("Default callback scheduled work.");
            invoked.Add(method);
            methods.Add(new { name = method.Name, token = method.MetadataToken, digest,
                resolvedCalleeMvid = callee.Module.ModuleVersionId, resolvedCalleeToken = callee.MetadataToken,
                patches = 0, completed = true, sameCachedTask = true });
        }
        if (invoked.Count != 98) throw new InvalidOperationException("Incomplete default task catalog.");
        Task[] workers = Enumerable.Range(0, 16).Select(_ => Task.Run(() =>
        {
            foreach (MethodInfo method in invoked)
            {
                var task = (Task)method.Invoke(receiver, new object?[method.GetParameters().Length])!;
                if (!ReferenceEquals(task, Task.CompletedTask) || !task.IsCompletedSuccessfully)
                    throw new InvalidOperationException("Parallel default callback changed task.");
            }
        })).ToArray();
        Task.WaitAll(workers);
        string after = ContinuationStamp.CaptureLive(live).StateText;
        if (before != after) throw new InvalidOperationException("Default callback queries changed live stamp.");
        string Sha(byte[] bytes) => Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();
        var result = new { gameMvid, framework = RuntimeInformation.FrameworkDescription,
            environmentVersion = Environment.Version.ToString(),
            coreLibrary = new { location = getter.Module.FullyQualifiedName,
                mvid = getter.Module.ModuleVersionId, sha256 = Sha(File.ReadAllBytes(getter.Module.FullyQualifiedName)),
                getterToken = getter.MetadataToken, getterIl = Convert.ToHexString(getterIl), getterIlSha256 = Sha(getterIl),
                field = completedField.Name, fieldToken = completedField.MetadataToken, fieldStaticReadonly = true },
            facade = new { name = facade.FullName, mvid = facade.ManifestModule.ModuleVersionId,
                location = facade.Location, sha256 = Sha(File.ReadAllBytes(facade.Location)) },
            methods, serialCalls = 98, parallelWorkers = 16, parallelCalls = 16 * 98,
            liveStampUnchanged = true, nativeMethodPatchCounts = 0, isWholeOrderCertificate = false,
            scope = "Direct default bodies and resolved getter only. No Hook dispatch, awaited task result, real gameplay arguments, Fork, state transition, order equivalence or pruning eligibility proof." };
        string request = UnattendedTestFiles.GlobalPath(UnattendedTestFiles.RequestUri);
        File.WriteAllText(Path.Combine(Path.GetDirectoryName(request)!, "default-task-binding-proof.json"),
            JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }) + "\n");
    }
}

